async function loadPublicCatalog(){
 const grid=$('#available-grid'),featured=$('#featured-carousel');
 if(!window.LKFBackend?.ready){if(grid)grid.innerHTML='<p class="center-note">The shop catalog is temporarily unavailable.</p>';return}
 if(grid)grid.innerHTML='<p class="center-note">Loading adoptables…</p>';
 try{
  const result=await window.LKFBackend.publicRequest('catalog');
  storeVisibility=['Public','Temporarily Closed','Hidden from Public'].includes(String(result.storeVisibility))?String(result.storeVisibility):'Temporarily Closed';
  adopts=(result.adopts||[]).map(row=>({id:row.id,name:row.name||'Untitled Adopt',category:row.category||'Other',price:Number(row.price||0),status:row.status||'Available',publicVisible:row.publicVisible!==false,archiveVisible:row.archiveVisible!==false,symbol:row.symbol||'✧',description:row.description||'',files:Array.isArray(row.files)?row.files:[],tags:Array.isArray(row.tags)?row.tags:[],featured:!!row.featured,images:Array.isArray(row.images)?row.images:[],mainImage:Math.max(0,Number(row.mainImage||0)),databaseId:row.databaseId||null}));
  customArchive=(result.customArchive||[]).filter(x=>x&&typeof x.imageUrl==='string'&&x.imageUrl).map(x=>({id:String(x.id||''),name:String(x.name||'Custom character'),category:String(x.category||'Custom design'),imageUrl:x.imageUrl,completedAt:x.completedAt||''}));
  refreshCategories();renderPublic();
 }catch(error){console.error('[Lady K ★ Fih] Catalog load failed',error);if(featured)featured.innerHTML='<p class="center-note">The catalog could not be loaded. Please refresh in a moment.</p>';if(grid)grid.innerHTML='<p class="center-note">The catalog could not be loaded. Please refresh in a moment.</p>'}
}
function renderAll(){
 try{renderPublic()}catch(error){console.error('[AdoptShop] Public view render failed:',error)}
 try{renderAdmin()}catch(error){console.error('[AdoptShop] Admin view render failed:',error)}
}
function renderCatalog(){const q=($('#catalog-search')?.value||'').trim().toLowerCase(),status=$('#status-filter')?.value||'',sort=$('#sort-filter')?.value||'default';let list=adopts.filter(a=>a.publicVisible!==false&&['Available','Reserved'].includes(a.status)).filter(a=>(activeCategory==='All categories'||a.category===activeCategory)&&(!status||a.status===status)&&(!q||`${a.name} ${a.id} ${a.category} ${(a.tags||[]).join(' ')}`.toLowerCase().includes(q)));list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='price-up'?a.price-b.price:sort==='price-down'?b.price-a.price:0);$('#available-grid').innerHTML=list.map(card).join('')||'<div class="center-note">No adoptables match your filters.</div>'}
function renderArchive(){const list=adopts.filter(a=>a.status==='Sold'&&a.archiveVisible!==false);$('#archive-grid').innerHTML=list.map(a=>card({...a,status:'Sold'})).join('')||'<div class="center-note">No sold adoptables are currently displayed.</div>';$('#archive-grid').querySelectorAll('[data-buy]').forEach(b=>b.remove())}
function renderCustomArchive(){const grid=$('#custom-archive-grid');if(!grid)return;grid.innerHTML=customArchive.map(x=>`<article class="adopt-card custom-archive-card"><div class="card-art"><img src="${esc(x.imageUrl)}" alt="${esc(x.name)} — completed Custom artwork" loading="lazy"></div><div class="card-body"><div class="card-overline"><span>${esc(x.category||'Custom design')}</span>${pill('Completed')}</div><h3 class="card-title">${esc(x.name||'Custom character')}</h3><p class="card-meta">Custom ID · ${esc(x.id)}</p><p class="card-detail">Completed ${esc(x.completedAt?new Date(x.completedAt).toLocaleDateString():'')}</p></div></article>`).join('')||'<div class="center-note">Completed Custom designs will appear here.</div>'}
function updateFeaturedControls(){const rail=$('#featured-carousel'),left=$('#featured-scroll-left'),right=$('#featured-scroll-right');if(!rail||!left||!right)return;const overflow=rail.scrollWidth>rail.clientWidth+4;left.disabled=!overflow||rail.scrollLeft<=2;right.disabled=!overflow||rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2}
function refreshCategories(){const cats=['All categories',...CATEGORIES];$('#category-filters').innerHTML=cats.map(c=>`<button class="chip ${activeCategory===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}
function goPage(page,{scroll=true,historyPush=true}={}){if(!['home','available','details','custom','archive','custom-archive','information','contact'].includes(page))page='home';currentPage=page;$$('[data-page]').forEach(x=>x.classList.toggle('hidden',x.dataset.page!==page));$$('#public-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===page));$('#public-nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');if(historyPush&&location.hash!==`#${page}`)history.pushState({page},'',`#${page}`);if(scroll)window.scrollTo({top:0,behavior:'smooth'});if(page==='home')setTimeout(updateFeaturedControls,0)}
