function renderDetail(a,detailIndex=a.mainImage||0){const canBuy=a.status==='Available'&&storeVisibility==='Public';const imgs=a.images||[];const hasArt=imgs.length>0;detailIndex=Math.min(detailIndex,Math.max(imgs.length-1,0));const featured=imgs[detailIndex];$('#adopt-detail-content').innerHTML=`<div class="page-hero gingham"><p class="eyebrow">Adoptable character</p><h1>${esc(a.name)}</h1><p class="lead">Individual adopt page · ${esc(a.id)}</p></div><section class="section detail-layout"><div><div class="detail-main-art placeholder-art" id="detail-main-art">${hasArt?`<img src="${esc(featured.url)}" alt="${esc(a.name)} — ${esc(featured.name||'main artwork')}" style="width:100%;height:100%;object-fit:contain">`:`<span>${esc(a.symbol)}<br>SINGLE IMAGE<br>PLACEHOLDER</span>`}</div>${hasArt&&imgs.length>1?`<div class="gallery-thumbs">${imgs.map((im,i)=>`<button class="gallery-thumb placeholder-art ${i===detailIndex?'selected':''}" type="button" data-gallery-index="${i}" aria-label="View ${esc(im.name||`image ${i+1}`)}">${im.url?`<img src="${esc(im.url)}" alt="${esc(im.name||'Gallery image')}" style="width:100%;height:100%;object-fit:cover">`:`<span>IMAGE ${i+1}</span>`}</button>`).join('')}</div><p class="fine">${imgs.length} artwork images · select a thumbnail to view.</p>`:`<p class="fine">${hasArt?'Only one artwork image is available for this adoptable.':'No additional gallery images are available.'}</p>`}</div><div class="detail-info"><p class="eyebrow">${esc(a.category)} · ${esc(a.status)}</p><h2>${esc(a.name)}</h2><p class="fine">ADOPT ID · ${esc(a.id)}</p><div class="thin"></div><h3>About this character</h3><p class="muted">${esc(a.description||'No description provided yet.')}</p><h3>Included files</h3><ul class="included-files">${(a.files||[]).map(f=>`<li>${esc(typeof f==='string'?f:f.name)}</li>`).join('')||'<li>No included files listed.</li>'}</ul><div class="total-line"><span>Base price</span><strong>${money(a.price)}</strong></div><h3>Choose a license</h3><div class="license-options" data-license-group="adopt"></div><div class="total-line"><span>License fee</span><strong id="adopt-license-fee">+${money(lic(currentLicense).fee)}</strong></div><div class="total-line"><span>Total</span><strong id="adopt-total">${money(total(a.price,currentLicense))}</strong></div><p class="fine">License conditions come from the <a href="https://ladykadopts.carrd.co/#" target="_blank" rel="noopener noreferrer" class="text-link">official Terms of Service</a>.</p>${canBuy?`<button class="btn primary" data-buy="${esc(a.id)}">Purchase Request</button>`:`<p class="request-summary">This adopt is ${esc(a.status.toLowerCase())}. Purchase requests are unavailable.</p>`}</div></section>`;renderLicenseOptions('adopt');$('#adopt-detail-content').onchange=e=>{if(e.target.name==='license'){currentLicense=e.target.value;$('#adopt-license-fee').textContent='+'+money(lic(currentLicense).fee);$('#adopt-total').textContent=money(total(a.price,currentLicense))}};$('#adopt-detail-content').onclick=e=>{const t=e.target.closest('[data-gallery-index]');if(t){renderDetail(a,Number(t.dataset.galleryIndex))}}}
function renderLicenseOptions(group){const el=$(`[data-license-group="${group}"]`);if(!el)return;const selected=group==='custom'?customLicense:currentLicense;el.innerHTML=LICENSES.map((l,i)=>`<label class="license-option"><input type="radio" name="license" value="${esc(l.name)}" required ${selected===l.name||(!selected&&i===0)?'checked':''}><span><strong>${esc(l.name)}</strong><small>${licenseShort(l.name)}</small></span><span class="price">+${money(l.fee)}</span></label>`).join('')}
