  form.classList.add('hidden');
  $('#custom-confirmation').innerHTML=`<div class="success"><h2>Custom Request Received</h2><p>Your request has been securely recorded.</p><div class="request-summary">Request <strong>${esc(request.order_code||request.id||'Received')}</strong><br>${esc(fullName)} · ${esc(email)} · Discord: ${esc(discord)}<br>Category: ${esc(payload.category)}<br>Base price: ${money(basePrice)}<br>License: ${esc(license)} (+${money(licenseFee)})<br><strong>Initial total: ${money(initialTotal)}</strong><br>Character name: ${esc(payload.character_name||'Not supplied yet')}<br>Concept: ${esc(payload.concept.slice(0,240))}${payload.concept.length>240?'…':''}<br>References securely uploaded: ${customFiles.length}</div><p>The artist will review your request and contact you separately. No payment has been collected.</p><button class="btn" id="new-custom-request">Start another request</button></div>`;
  $('#new-custom-request').onclick=()=>{form.reset();form.dataset.submitting='false';form.classList.remove('hidden');$('#custom-confirmation').innerHTML='';customFiles=[];$('#reference-previews').replaceChildren();$('#file-hint').textContent='No images selected.';resetCustomLicense();submit.disabled=false;submit.textContent='Submit Custom Adopt Request'};
