  if(!/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(id))errors.push('Adopt ID may contain letters, numbers, hyphens and underscores (up to 80 characters).');
  if(!Number.isFinite(price)||price<0)errors.push('Enter a valid non-negative price.');
