function renderPurchaseRequests(){const query=($('#purchase-search').value||'').toLowerCase(),status=$('#purchase-filter').value;const list=purchaseRequests.filter(r=>(!status||r.status===status)&&(!query||`${r.id} ${r.fullName} ${r.email} ${r.discord} ${r.adoptId} ${adopts.find(a=>a.id===r.adoptId)?.name||''}`.toLowerCase().includes(query)));workspaceSummary('purchase-summary',`${list.length} requests shown · ${purchaseRequests.filter(r=>r.status==='Pending Review').length} pending review · ${purchaseRequests.filter(r=>r.paymentPending&&!r.paid).length} payments awaiting confirmation.`);$('#purchase-list').innerHTML=list.map(r=>{const a=adopts.find(x=>x.id===r.adoptId);return `<article class="admin-card request-card purchase-click-card" data-purchase-card="${esc(r.id)}"><div class="admin-title request-heading"><div class="request-thumb">${a?artMarkup(a,null,true):'<span>—</span>'}</div><div><h2>${esc(r.id)} · ${esc(a?.name||r.adoptId)}</h2><p>${esc(r.fullName)} · ${esc(r.discord)} · ${esc(r.date)} · Submitted request</p></div>${pill(r.status)}</div><p>Base ${money(r.basePrice)} + license ${money(r.licenseFee)} = <b>${money(r.total)}</b> · Payment: ${esc(r.paymentStatus)}</p><button class="btn small" data-pr="open" data-id="${esc(r.id)}">Open complete request →</button></article>`}).join('')||'<div class="admin-empty">No purchase requests match.</div>'}
async function reviewCertificateRecord(record,decision,kind){
 if(!record?.certificateId){toast('No database certificate is linked to this record yet.',true);return}
 const verb=decision==='approve'?'approve':'reject';
 if(!confirm('Are you sure you want to '+verb+' certificate '+record.certificate+'? This records your review and does not send the certificate.'))return;
 try{
  await window.LKFBackend.admin('review-certificate',{id:record.certificateId,decision});
  await loadAdminData();renderAll();
  const fresh=kind==='purchase'?purchaseRequests.find(x=>x.databaseId===record.databaseId):customRequests.find(x=>x.databaseId===record.databaseId);
  if(fresh){if(kind==='purchase')openPurchaseDetail(fresh);else openCustomDetail(fresh)}
 }catch(error){toast(error?.message||'Certificate review could not be saved.',true)}
}
function openPurchaseDetail(r){const a=adopts.find(x=>x.id===r.adoptId),o=ownership.find(x=>x.adoptId===r.adoptId),sum=`<div class="record-hero"><div class="record-hero-art">${a?artMarkup(a):'<span>—</span>'}</div><div><p class="eyebrow">Premade Purchase Request</p><h3>${esc(r.id)}</h3><p>${esc(a?.name||r.adoptId)} · ${esc(r.adoptId)} · ${esc(r.fullName)}</p><p>${pill(r.status)} ${pill(r.paymentStatus||'Payment pending')} · <b>${money(r.total)}</b></p></div></div>`,content=sum+adminAccordion('1 — Buyer Information','♙','Private contact details submitted with the request.',`<p>Full name: ${esc(r.fullName)}</p><p>Email: ${esc(r.email)}</p><p>Discord: ${esc(r.discord)}</p><p>Submitted: ${esc(r.date)} · ToS accepted: ${r.termsAccepted?'Yes':'No'}</p>`)+adminAccordion('2 — Adopt & License Details','✧','Selected character and price breakdown.',`<p>Adopt: ${esc(a?.name||'Record missing')} · ${esc(r.adoptId)} · ${esc(a?.category||'Unknown category')}</p><p>License: ${esc(r.license)}</p><p>Base price: ${money(r.basePrice)} · License fee: ${money(r.licenseFee)} · Total: <b>${money(r.total)}</b></p><p>Inventory: ${esc(a?.status||'Missing')} · ${a?.publicVisible===false?'Hidden':'Published'}</p>`)+adminAccordion('3 — Request Review','✓','Approval does not mean payment.',`<p>Current request status: ${pill(r.status)}</p><p>Approval is a review decision only; the adopt remains Reserved until payment is manually confirmed.</p>`)+adminAccordion('4 — Invoice & Payment Management','＄','Payment is never verified automatically.',`<p>Invoice: ${r.invoiceSent?'Marked sent':'Not marked sent'}</p><p>Payment status: ${esc(r.paymentStatus)} · ${r.paid?'Confirmed '+esc(r.paidDate):'Awaiting manual confirmation'} · Method: ${esc(r.paymentMethod||'Not recorded')}</p><p>Payment confirmation history: ${r.paid?`Full payment manually confirmed ${esc(r.paidDate||'date not recorded')} · ${money(r.total)}`:'No payment confirmation recorded.'}</p><p>Expected full amount: <b>${money(r.total)}</b></p><p class="fine">After manual full-payment confirmation, explicitly mark the adopt Sold in a separate action to update its archive and ownership record.</p>`)+adminAccordion('5 — Reservation Management','⌁','Reservations never expire or release automatically.',`<p>Inventory status: ${esc(a?.status||'Missing')}</p><p>Request status: ${esc(r.status)}</p><p>Rejecting or cancelling does not release a reservation. Release is a separate manual action.</p>`)+adminAccordion('Delivery Status','⇢','Retain the manual delivery status tool.',`<p>Delivery: ${r.delivered?'Delivered':'Not delivered'}</p>`)+adminAccordion('6 — Ownership & Certificate','✦','Shown after payment is confirmed.',`<p>Current owner: ${esc(o?.current?.name||'Not registered')}</p><p>Ownership history: ${(o?.history||[]).map(h=>`${esc(h.kind)} · ${esc(h.name)} · ${esc(h.date)} · ${esc(h.certificate)}`).join('<br>')||'None yet'}</p><p>Certificate: ${esc(o?.current?.certificate||'Unavailable until payment confirmation')}</p>`),actions=[{group:'3 — Request Review',label:'Approve Request',hint:'Approval is not payment and does not complete a sale.',action:m=>{m.remove();purchaseAction(r.id,'approve')}},{group:'3 — Request Review',label:'Reject Request',hint:'The reservation remains until manually released.',action:m=>{m.remove();purchaseAction(r.id,'reject')}},{group:'3 — Request Review',label:'Request Clarification',hint:'Records the need for clarification only; no message is sent.',action:m=>{m.remove();purchaseAction(r.id,'clarify')}},{group:'4 — Invoice & Payment Management',label:r.invoiceSent?'Invoice Already Marked Sent':'Mark Invoice as Sent',hint:'Records that you manually sent the invoice; this action does not send an invoice automatically.',action:m=>{m.remove();purchaseAction(r.id,'invoice')}},{group:'4 — Invoice & Payment Management',label:'Record Payment Method',hint:'Saves the recorded payment method in the private Supabase purchase record. No payment service is contacted.',action:m=>{m.remove();purchaseAction(r.id,'payment-method')}},{group:'4 — Invoice & Payment Management',label:r.paymentPending?'Payment Already Pending':'Mark Payment Pending',hint:`Expected total ${money(r.total)}. Saves the pending manual-verification status in Supabase; it does not verify or collect payment.`,action:m=>{m.remove();purchaseAction(r.id,'pending')}},{group:'4 — Invoice & Payment Management',label:r.paid?'Payment Confirmed':'Confirm Payment',primary:true,hint:`Manually verify the full ${money(r.total)} amount. Payment confirmation does not mark the adopt Sold.`,action:m=>{m.remove();purchaseAction(r.id,'paid')}},,{group:'5 — Reservation Management',label:'Return Adoptable to Available',disabled:!a||a.status!=='Reserved'||r.paid||a.reservationRequestId!==r.id,hint:'Manual only; keeps the request and payment history.',action:m=>{m.remove();purchaseAction(r.id,'return-available')}},,{group:'Delivery Status',label:r.delivered?'Completed':'Complete Order',disabled:!r.paid||r.delivered,hint:'Use only after you have actually delivered the adoptable. This completes the sale, archive, ownership and certificate review record.',action:m=>{m.remove();purchaseAction(r.id,'delivery')}},,{group:'6 — Ownership & Certificate',label:'Open Associated Adopt',action:m=>{m.remove();if(a)openAdoptRecord(a)}},{group:'6 — Ownership & Certificate',label:'View Ownership & Transfer History',action:m=>{m.remove();openOwnershipRecord(r.adoptId)}},{group:'6 — Ownership & Certificate',label:'Approve Certificate',primary:true,disabled:!r.certificateId||r.certificateStatus!=='Pending Review',hint:'Approve the certificate generated by the completed delivery workflow.',action:m=>{m.remove();reviewCertificateRecord(r,'approve','purchase')}},{group:'6 — Ownership & Certificate',label:'Reject Certificate',disabled:!r.certificateId||r.certificateStatus!=='Pending Review',hint:'Reject this certificate for correction; the record remains in history.',action:m=>{m.remove();reviewCertificateRecord(r,'reject','purchase')}},{group:'6 — Ownership & Certificate',label:'Preview / Print / Download Certificate',action:m=>{m.remove();if(r.paid&&r.certificate)openCertificatePreview(`purchase:${r.id}`);else toast('Generate the certificate after confirmed payment and Sold status.',true)}}];openModal(`Purchase Request · ${r.id}`,content,actions)}
