function renderCustomArchiveAdmin(){const q=($('#custom-archive-search')?.value||'').toLowerCase();const list=customRequests.filter(r=>customStatusLabel(r)==='Completed'&&(!q||`${r.id} ${r.characterName} ${r.category}`.toLowerCase().includes(q)));workspaceSummary('custom-archive-summary',`${list.length} completed Customs · public artwork archive.`);$('#admin-custom-archive-list').innerHTML=list.map(r=>`<article class="admin-card request-card custom-archive-admin-card" data-custom-card="${esc(r.id)}"><div class="admin-title"><div><h2>${esc(r.id)} · ${esc(r.characterName||'Custom character')}</h2><p>${esc(r.category)} · Completed ${esc(r.deliveryDate||'')}</p></div>${pill('Completed')}</div>${r.finalArtwork?.url?`<div class="final-art-preview"><img src="${esc(r.finalArtwork.url)}" alt="${esc(r.characterName||'Custom artwork')} final artwork"></div>`:'<p class="fine">No final artwork is available for this completed record.</p>'}<button class="btn small" data-custom-open="${esc(r.id)}">Open completed record →</button></article>`).join('')||'<div class="admin-empty">No completed Custom orders yet.</div>'}
function openCustomDetail(r){const agreed=Number(r.quoteBase||0)+Number(r.licenseFee||0),own=ownership.find(o=>o.adoptId===`CUSTOM-${r.id}`),refs=r.files?.length?`<div class="image-preview">${r.files.map(f=>`<figure><img src="${esc(f.url)}" alt="${esc(f.name)}"><figcaption>${esc(f.name)} · ${(Number(f.size||0)/1048576).toFixed(2)} MB · CLIENT REFERENCE</figcaption></figure>`).join('')}</div>`:'<p>No reference images supplied.</p>',summary=`<div class="record-hero"><div><p class="eyebrow">Custom Adopt · private request</p><h3>${esc(r.id)} · ${esc(r.characterName||'Name not supplied')}</h3><p>${esc(r.fullName)} · ${esc(r.license)} · submitted ${esc(r.date)}</p><p>${pill(customStatusLabel(r))} · ${esc(customPaymentSummary(r))}</p><div class="field inline-status-field"><label for="custom-status-${esc(r.id)}">Order Status</label><select id="custom-status-${esc(r.id)}">${['New Request','In Progress','Awaiting Payment','Awaiting Approval','Ready for Delivery','Completed','Cancelled'].map(v=>`<option ${customStatusLabel(r)===v?'selected':''}>${v}</option>`).join('')}</select><button class="btn small" data-custom-status-save="${esc(r.id)}">Save Status</button></div></div>`,content=summary+adminAccordion('1 — Client Information','♙','Private contact and submitted terms.',`<p>${esc(r.fullName)} · ${esc(r.email)} · ${esc(r.discord)}</p><p>Category: ${esc(r.category)} · License: ${esc(r.license)} · ToS accepted: ${r.termsAccepted?'Yes':'No'}</p>`)+adminAccordion('2 — Design Brief & References','✧','Concept, appearance and client-supplied reference materials.',`<p>Character name: ${esc(r.characterName||'Not supplied')}</p><p>Concept: ${esc(r.concept)}</p><p>Appearance: ${esc(r.appearance)}</p><p>Colors: ${esc(r.colors)} · Clothing/accessories: ${esc(r.clothing)}</p><p>Personality/theme: ${esc(r.theme)} · Additional instructions: ${esc(r.instructions)}</p><p>External links: ${esc(r.links)}</p>${refs}`)+adminAccordion('3 — Quote Management','＄','Quote preparation and client approval are manual.',`<p>Design quote: ${r.quoteBase?money(r.quoteBase):'Not set'} + license ${money(r.licenseFee)} = <b>${r.quoteBase?money(agreed):'Not set'}</b></p><p>Quote date: ${esc(r.quoteDate||'Not set')} · Sent: ${r.quoteSent?'Yes':'No'} · Client approval: ${r.clientApprovedQuote?'Recorded':'Pending'}</p><p>Payment plan: ${r.paymentPlan==='full'?'Full Payment · 100%':'Split Payment · 60% + 40%'} · Payment method: ${esc(r.paymentMethod||'Not recorded')}</p><p>Full amount due: ${money(agreed)} · Initial 60%: ${money(agreed*.6)} · Final 40%: ${money(agreed*.4)}</p><p>Payment status: ${r.fullPaid?'Full payment · Confirmed':`Initial · ${r.initialPaid?'Confirmed':'Pending'} · Final · ${r.finalPaid?'Confirmed':'Pending'}`}</p><p>Payment history: ${(r.paymentHistory||[]).map(x=>`${esc(x.stage)} · ${money(x.amount)} · ${esc(x.status)} · ${esc(x.date||'')}`).join('<br>')||'No confirmed payments.'}</p><button class="btn small" data-custom-plan="${esc(r.id)}">Set Agreed Price &amp; Payment Plan</button>`)+adminAccordion('4 — Initial Payment · 60%','＄','Work can begin after manual confirmation.',`<p>Expected initial payment: ${r.quoteBase?money(agreed*.6):'Set quote first'} · Status: ${r.initialPaid?'Manually confirmed · '+esc(r.initialPaidDate):'Pending'}</p><p>No payment is received or verified automatically.</p>`)+adminAccordion('5 — Design Progress','✎','Manual progress notes, client feedback and final art.',`<p>Current stage: ${esc(r.progress||r.status)}</p><p>Progress history: ${(r.progressHistory||[]).map(x=>`${esc(x.date)} · ${esc(x.text)}`).join('<br>')||'No progress updates.'}</p><p>Client feedback: ${(r.feedback||[]).map(x=>`${esc(x.date)} · ${esc(x.text)}`).join('<br>')||'None recorded.'}</p>${r.finalArtwork?.url?`<div class="final-art-preview"><p class="eyebrow">ARTIST-SELECTED FINAL ART · NOT CLIENT REFERENCE</p><img src="${esc(r.finalArtwork.url)}" alt="${esc(r.characterName||'Custom character')} final artwork"><p>${esc(r.finalArtwork.name||'Final artwork')}</p></div>`:'<p class="fine">No dedicated final artwork yet. Client references are never used as certificate art.</p>'}`)+adminAccordion('6 — Revision Suggestions','✎','Review each suggestion individually; no fixed numerical limit.',(r.suggestions||[]).map((x,i)=>`<label class="suggestion-row"><span>${esc(x.text)}</span><select data-suggestion-status="${i}" data-id="${esc(r.id)}">${['Pending Review','Accepted','Declined','Completed'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')||'<p>No revision suggestions recorded.</p>')+adminAccordion('7 — Final Approval','✓','Artist records preview presentation and final approval.',`<p>Preview presented: ${r.previewPresented?'Yes · '+esc(r.previewDate):'No'}</p><p>Final approval: ${r.finalApproved?'Recorded · '+esc(r.finalApprovalDate):'Pending'}</p>`)+adminAccordion('8 — Final Payment · 40%','＄','Certificate eligibility requires manually confirmed final payment.',`<p>Expected final payment: ${r.quoteBase?money(agreed*.4):'Set quote first'} · Status: ${r.finalPaid?'Manually confirmed · '+esc(r.finalPaidDate):'Pending'}</p><p>No payment is collected or verified automatically.</p>`)+adminAccordion('9 — Delivery & Certificate','✦','Delivery is a separate manual step; no file or message is sent.',`<p>Delivery: ${r.deliverySimulated?'Registered · '+esc(r.deliveryDate):'Not recorded'}</p><p>Ownership: ${esc(own?.current?.name||'Created after final payment confirmation')} · License ${esc(own?.current?.license||r.license)}</p><p>Certificate: ${esc(own?.current?.certificate||r.certificate||'Unavailable until final payment')}</p><p>Ownership history: ${(own?.history||[]).map(h=>`${esc(h.kind)} · ${esc(h.name)} · ${esc(h.date)} · ${esc(h.certificate)}`).join('<br>')||'None recorded'}</p>`),actions=[{group:'1 — Client Information',label:'Accept Request',hint:'Accepting a request is a manual review decision.',action:m=>{m.remove();customAction(r.id,'approve')}},{group:'1 — Client Information',label:'Reject Request',action:m=>{m.remove();customAction(r.id,'reject')}},{group:'1 — Client Information',label:'Request Clarification',hint:'Records the step only; does not send a message.',action:m=>{m.remove();customAction(r.id,'clarify')}},{group:'3 — Quote Management',label:'Set / Edit Quote',action:m=>{m.remove();customAction(r.id,'quote')}},{group:'3 — Quote Management',label:'Mark Quote Sent',hint:'No email/message is sent.',action:m=>{m.remove();customAction(r.id,'quote-send')}},{group:'3 — Quote Management',label:'Record Client Approval',action:m=>{m.remove();customAction(r.id,'client-approve')}},{group:'4 — Initial Payment · 60%',label:'Confirm Initial 60%',primary:true,disabled:r.paymentPlan==='full'||r.initialPaid,hint:`Expected: ${money(agreed*.6)}. Manual confirmation only.`,action:m=>{m.remove();customAction(r.id,'initial')}},{group:'4 — Initial Payment · 60%',label:'Confirm Full Payment · 100%',disabled:r.paymentPlan!=='full'||r.fullPaid,hint:`For Full Payment plans: ${money(agreed)}. Independent manual confirmation.`,action:m=>{m.remove();customAction(r.id,'full-payment')}},{group:'5 — Design Progress',label:'Update Progress',action:m=>{m.remove();customAction(r.id,'progress')}},{group:'5 — Design Progress',label:'Record Client Feedback',action:m=>{m.remove();customAction(r.id,'feedback')}},{group:'5 — Design Progress',label:'Add Private Note',action:m=>{m.remove();customAction(r.id,'note')}},{group:'5 — Design Progress',label:'Set Character Name / Final Art',action:m=>{m.remove();customAction(r.id,'artwork')}},{group:'6 — Revision Suggestions',label:'Add Revision Suggestion',action:m=>{m.remove();customAction(r.id,'suggest')}},{group:'7 — Final Approval',label:'Record Preview Presented',action:m=>{m.remove();customAction(r.id,'preview')}},{group:'7 — Final Approval',label:'Record Final Approval',action:m=>{m.remove();customAction(r.id,'final-approval')}},{group:'8 — Final Payment · 40%',label:'Confirm Final 40%',primary:true,disabled:r.paymentPlan==='full'||!r.initialPaid||!r.finalApproved||r.finalPaid,hint:`Expected: ${money(agreed*.4)}. Manual confirmation enables certificate eligibility.`,action:m=>{m.remove();customAction(r.id,'final')}},{group:'9 — Delivery & Certificate',label:'Complete Order',disabled:!(r.fullPaid||r.finalPaid)||!r.finalApproved||!r.characterName?.trim()||!r.finalArtwork?.url||r.deliverySimulated,hint:'Use only after the finished Custom Adopt has actually been delivered. Completion creates its ownership record and certificate for review.',action:m=>{m.remove();customAction(r.id,'delivery')}},{group:'9 — Delivery & Certificate',label:'View Ownership & Transfer History',action:m=>{m.remove();openOwnershipRecord(`CUSTOM-${r.id}`)}},{group:'9 — Delivery & Certificate',label:'Record Eligible Ownership Transfer',action:m=>{m.remove();if(own&&own.current?.license==='Full Rights Transfer')transferOwner(`CUSTOM-${r.id}`);else toast('Transfer is unavailable for this license.',true)}},{group:'9 — Delivery & Certificate',label:'Approve Certificate',primary:true,disabled:!r.certificateId||r.certificateStatus!=='Pending Review',hint:'Approve the certificate automatically created after completed delivery.',action:m=>{m.remove();reviewCertificateRecord(r,'approve','custom')}},{group:'9 — Delivery & Certificate',label:'Reject Certificate',disabled:!r.certificateId||r.certificateStatus!=='Pending Review',hint:'Reject this certificate for correction; the record remains in history.',action:m=>{m.remove();reviewCertificateRecord(r,'reject','custom')}},{group:'9 — Delivery & Certificate',label:'Edit Certificate Information',disabled:true,hint:'Certificate details are generated from the completed Custom Adopt record and are not editable here.'},{group:'9 — Delivery & Certificate',label:'Preview / Print / Download Certificate',action:m=>{m.remove();if(r.certificate&&(r.finalPaid||r.fullPaid)&&customStatusLabel(r)==='Completed')openCertificatePreview(`custom:${r.id}`);else toast('Generate the certificate manually after completion and confirmed payment.',true)}},{group:'9 — Delivery & Certificate',label:'Cancel Request',action:m=>{m.remove();customAction(r.id,'cancel')}}];openModal(`Custom Record · ${r.id}`,content,actions)}
function askText(title,placeholder,callback){const content=`<label class="field">${esc(title)}<textarea id="modal-text" placeholder="${esc(placeholder)}"></textarea></label>`;openModal(title,content,[{label:'Save note',primary:true,action:m=>{const v=m.querySelector('#modal-text').value.trim();if(!v){toast('Enter text before saving.',true);return}callback(v);m.remove();renderAll()}},{label:'Cancel',action:m=>m.remove()}])}
function editCustomCharacter(r){
 const root=document.createElement('div');root.className='modal-backdrop';
 const art=r.finalArtwork?.url?'<img src="'+esc(r.finalArtwork.url)+'" alt="Current finished character artwork"><p>'+esc(r.finalArtwork.name||'Final artwork')+'</p>':'<p class="fine">No finished character artwork supplied yet.</p>';
 root.innerHTML='<section class="modal-card" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close">×</button><p class="eyebrow">Private final artwork</p><h2>Character Name &amp; Final Artwork</h2><p class="muted">This artwork is separate from client references. It will be uploaded to the private delivery bucket and only shown to the administrator through a temporary signed URL.</p><label class="field">Finished character name<input id="final-character-name" value="'+esc(r.characterName||'')+'" placeholder="Character name"></label><label class="field">Finished character artwork<input id="final-character-art" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif"><span class="fine">Image only · maximum 20 MB.</span></label><div class="final-art-preview">'+art+'</div><label class="checkline"><input id="remove-final-art" type="checkbox"> Clear the current final artwork reference</label><div id="final-art-error"></div><div class="actions"><button class="btn primary" id="save-final-art">Save Character Details</button></div></section>';
 document.body.append(root);let file=null,pendingFinalArtworkPath=null;
 root.querySelector('.modal-close').onclick=()=>root.remove();
 root.addEventListener('click',e=>{if(e.target===root)root.remove()});
 root.querySelector('#final-character-art').addEventListener('change',e=>{
  file=e.target.files[0]||null;
  if(!file)return;
  if(!file.type.startsWith('image/')||file.size>20*1024*1024){
   file=null;e.target.value='';root.querySelector('#final-art-error').innerHTML=errorBox(['Choose an image file up to 20 MB.']);return;
  }
  const img=document.createElement('img');img.src=URL.createObjectURL(file);img.alt='Selected final artwork preview';img.style='max-width:180px;max-height:180px;object-fit:contain';
  root.querySelector('.final-art-preview').replaceChildren(img);
  const caption=document.createElement('p');caption.textContent=file.name;root.querySelector('.final-art-preview').append(caption);
  root.querySelector('#remove-final-art').checked=false;
 });
 root.querySelector('#save-final-art').onclick=async()=>{
  const button=root.querySelector('#save-final-art'),error=root.querySelector('#final-art-error'),name=root.querySelector('#final-character-name').value.trim();
  button.disabled=true;button.textContent='Saving…';error.innerHTML='';
  try{
   let path=r.finalArtwork?.storagePath||null;
   if(file){
    const ticket=await window.LKFBackend.admin('create-final-artwork-upload',{custom_order_id:r.databaseId,filename:file.name,content_type:file.type,file_size:file.size});
    pendingFinalArtworkPath=ticket.path;
    const uploaded=await window.LKFBackend.client.storage.from('private-deliveries').uploadToSignedUrl(ticket.path,ticket.token,file,{contentType:file.type,upsert:false});
    if(uploaded.error)throw uploaded.error;
    path=ticket.path;
   }else if(root.querySelector('#remove-final-art').checked){path=null}
   const saved=await persistCustomUpdate(r,{character_name:name||null,final_artwork_path:path});
   if(!saved)throw new Error('The final artwork reference could not be saved.');
   pendingFinalArtworkPath=null;
   root.remove();renderAll();openCustomDetail(saved);
  }catch(err){
   if(pendingFinalArtworkPath){const path=pendingFinalArtworkPath;pendingFinalArtworkPath=null;try{await window.LKFBackend.admin('cleanup-final-artwork-upload',{custom_order_id:r.databaseId,path})}catch(cleanupError){console.error('[AdoptShop] Temporary final artwork cleanup failed:',cleanupError)}}
   error.innerHTML=errorBox([err?.message||'Final artwork could not be saved.']);
   button.disabled=false;button.textContent='Save Character Details';
  }
 };
}
async function persistCustomUpdate(r,values){
 try{await window.LKFBackend.admin('update-custom-order',{id:r.databaseId,values});await loadAdminData();return customRequests.find(x=>x.databaseId===r.databaseId)||null}
 catch(error){toast(error?.message||'Custom order could not be updated.',true);return null}
}
