if(key.startsWith('custom:')){const r=customRequests.find(x=>x.id===key.slice(7));if(!(r?.finalPaid||r?.fullPaid))return null;const o=ownership.find(x=>x.adoptId===`CUSTOM-${r.id}`),license=o?.current?.license||r.license,number=[o?.current?.certificate,r.certificate].find(v=>v&&v!=='Not generated'&&v!=='Not available');if(!number)return null;return {number,adoptId:`CUSTOM-${r.id}`,name:r.characterName||'Name not supplied · incomplete record',creator:'Lady K ★ Fih',owner:o?.current?.name||r.fullName,license,date:o?.current?.date||r.finalPaidDate,price:o?.current?.price??(r.quoteBase+r.licenseFee),tos:$('#tos-version').value||'Official Terms of Service · version not recorded',seal:lic(license).seal,incomplete:!r.characterName||!r.finalArtwork,image:r.finalArtwork?.url||null,imageLabel:r.finalArtwork?.name||'Final character artwork not supplied'}}
